// Package bundled embeds the Redocly-bundled OpenAPI document the server
// serves at GET {PathPrefix}/openapi.json. The JSON is generated by
// scripts/bundle-openapi.mjs; never edit it by hand.
package bundled

import (
	"bytes"
	_ "embed"
	"net/http"
	"time"

	"github.com/zitadel/nextgen/api/client"
)

//go:embed openapi.json
var document []byte

// Path is where MountAPI mounts the document (ADR 077 prefix).
var Path = client.PathPrefix + "/openapi.json"

// Handler serves the embedded OpenAPI document. Mounted by MountAPI outside
// the ogen chain so discovery needs no auth. CORS * is for cross-origin GET
// from API tools; there is no OPTIONS route — simple GETs do not preflight.
func Handler() http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Method != http.MethodGet && r.Method != http.MethodHead {
			w.Header().Set("Allow", "GET, HEAD")
			http.Error(w, http.StatusText(http.StatusMethodNotAllowed), http.StatusMethodNotAllowed)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		w.Header().Set("Cache-Control", "public, max-age=300")
		w.Header().Set("Access-Control-Allow-Origin", "*")
		http.ServeContent(w, r, "openapi.json", time.Time{}, bytes.NewReader(document))
	})
}
